using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now uses UTC for seeding timestamps.
        // Use a fixed value instead of DateTime.UtcNow to avoid generating a new
        // migration on every run.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfApp");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 Cosmos provider now uses "$type" instead of
        // "Discriminator" by default. For existing documents that already store
        // "Discriminator", explicitly configure the property name to preserve
        // backward compatibility.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// Demonstrates fix for breaking change 2: Synchronous I/O on Cosmos is no longer
// supported in EF Core 9. All queries/saves must use async methods.
class CosmosQueryService
{
    // BEFORE (EF Core 8 — synchronous, now throws InvalidOperationException in EF 9):
    //   var products = db.Products.Where(p => p.Category == "Books").ToList();
    //
    // AFTER (EF Core 9 — must use async):
    public async Task<List<Product>> GetProductsByCategoryAsync(CosmosDbContext db, string category)
    {
        return await db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task SaveProductAsync(CosmosDbContext db, Product product)
    {
        db.Products.Add(product);
        await db.SaveChangesAsync();
    }
}

